// 127227--METVendTableProcessDelete
class METVendTableProcessDelete extends RunBaseBatch implements BatchRetryable
{
    // Packed variables
    TransDate       transDate;
    CustAccount     custAccount;
    VendTable       vendtable;
    METVendTable    metvendtable;
    // Dialog fields
    DialogField     dlgCustAccount;
    DialogField     dlgTransDate;
    DialogField dialogPerformDelete;
    DialogField dlgVendAccount;

    boolean                performDelete;
    Name VendAccountNum;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        transDate,
        custAccount
    #endmacro
}

