/// <summary>
///    Indicates whether the class is shown in the list of <c>Journal</c> types.
/// </summary>
/// <returns>
///    true if the class is shown in the list of <c>Journal</c> types; otherwise, false.
/// </returns>
/// <remarks>
///    A class that can be used in a batch journal is a class where the same parameters can be used
///    repeatedly. The dialog box can be shown and the parameters can be changed, but parameters of some
///    classes might build on data that is only valid for a short time. Running a class two times with the
///    same parameters is not always possible. If the <c>RunBaseBatch.canGoBatch</c> method is false, this
///    method will not have any effect.
/// </remarks>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
///    Returns a class that contains the methods that are described by the <c>RunBaseDialogable</c>
///    interface.
/// </summary>
/// <returns>
///    A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
///    A dialog box can be either built by using the <c>Dialog</c> class or by using a class that is
///    created in the Application Object Tree (AOT).
/// </remarks>
public Object dialog()
{
    DialogRunbase       dialog = super();
    #resAppl
    ;
   
    dialogPerformDelete=dialog.addFieldValue(extendedTypeStr(NoYesId),performDelete,"@MCR34087");
    dlgVendAccount = dialog.addField(extendedTypeStr(name),'METVendAccount');
    dlgVendAccount.registerOverrideMethod(methodStr(FormStringControl, lookup),methodStr(METVendTableProcessDelete, vendLookup), this);
    return dialog;
}

    public void vendLookup(FormStringControl _control)
    {
        SysTableLookup sysTableLookup;
        QueryBuildDataSource qbds;

        Query query = new Query();
        qbds = Query.addDataSource(tableNum(METVendTable));
        sysTableLookup = SysTableLookup::newParameters(tableNum(METVendTable), _control,true);
        sysTableLookup.addLookupfield(fieldNum(METVendTable, AccountNum), true);
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

public boolean getFromDialog()
{
    performDelete=dialogPerformDelete.value();
    VendAccountNum=dlgVendAccount.value();
    return super();
}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
public void run()
{
    #OCCRetryCount
   
  
    try
    {
        ttsbegin;
        if(VendAccountNum)
        {
           
            select firstonly forupdate  metvendtable  where metvendtable.AccountNum ==   VendAccountNum;
            if(metvendtable)
            {
                Info(strFmt("@MET:METVendProcessDelete1",VendAccountNum));
            }
            if(performDelete == Noyes::Yes)
            {
                metvendtable.delete();
            }
        }
        else
        {
            while select forupdate  metvendtable notexists join vendtable where metvendtable.AccountNum ==   vendtable.AccountNum
            {
                Info(strFmt("@MET:METVendProcessDelete1",metvendtable.AccountNum));
                if(performDelete == Noyes::Yes)
                {
                    metvendtable.delete();
                }
            }
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

    public boolean unpack(container packedClass)
    {
        Version version = RunBase::getVersion(packedClass);
        ;
        switch (version)
        {
            case #CurrentVersion:
                [version,#CurrentList] = packedClass;
                break;
            default:
                return false;
        }

        return true;
    }

    public boolean validate(Object _calledFrom = null)
    {
        if (false)
            return checkFailed("");

        return true;
    }

static METVendTableProcessDelete construct()
{
    return new METVendTableProcessDelete();
}

