static ClassDescription description()
{
    return "@MET:METVendProcessDelete2";
}

    static void main(Args args)
    {
        METVendTableProcessDelete    tutorial_RunBase;
        ;
        tutorial_RunBase = METVendTableProcessDelete::construct();

        if (tutorial_RunBase.prompt())
            tutorial_RunBase.runOperation();
    }

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
